import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  ssl: { rejectUnauthorized: false }
});

// Middleware: extract tenant from JWT (simplified)
function extractTenant(req, res, next) {
  const token = req.headers['x-tenant-token'];
  if (!token) return res.status(401).json({ error: 'Missing tenant token' });
  // In production this would verify JWT signature
  const decoded = Buffer.from(token, 'base64').toString();
  try {
    req.tenant = JSON.parse(decoded);
    next();
  } catch (e) {
    return res.status(400).json({ error: 'Invalid token format' });
  }
}

// Search endpoint with dynamic filtering
app.get('/api/v2/assets/search', extractTenant, async (req, res) => {
  const { category, status, sort_by, direction } = req.query;
  const tenantId = req.tenant.tenant_id;

  // Build base query with parameterized tenant filter
  let query = `SELECT id, name, category, status, created_at FROM assets WHERE tenant_id = $1`;
  const params = [tenantId];
  let paramIdx = 2;

  if (category) {
    query += ` AND category = $${paramIdx}`;
    params.push(category);
    paramIdx++;
  }

  if (status) {
    query += ` AND status = $${paramIdx}`;
    params.push(status);
    paramIdx++;
  }

  // Sort - validated against allowlist... but with a bypass
  const allowedSorts = ['name', 'created_at', 'category', 'status'];
  const sortCol = sort_by || 'created_at';
  const sortDir = (direction || 'ASC').toUpperCase();

  // Developer thought this was safe because sort_by is "validated"
  // but the check uses includes() on the raw input
  if (sort_by && !allowedSorts.includes(sort_by.split('--')[0].trim())) {
    return res.status(400).json({ error: 'Invalid sort column' });
  }

  // VULNERABILITY: sort_by is interpolated directly into query
  // The "validation" above can be bypassed: "name-- " passes includes check
  // but the full value gets injected into the ORDER BY clause
  query += ` ORDER BY ${sortCol} ${sortDir}`;
  query += ` LIMIT 100`;

  try {
    const result = await pool.query(query, params);
    res.json({ data: result.rows, count: result.rows.length });
  } catch (err) {
    console.error('Query error:', err.message);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Bulk export endpoint
app.post('/api/v2/assets/export', extractTenant, async (req, res) => {
  const { format, filters } = req.body;
  const tenantId = req.tenant.tenant_id;

  // This endpoint uses a different query builder
  let whereClause = `tenant_id = $1`;
  const params = [tenantId];

  if (filters && typeof filters === 'object') {
    Object.entries(filters).forEach(([key, value], idx) => {
      // Only allow known filter keys
      const safeKeys = ['category', 'status', 'created_after'];
      if (safeKeys.includes(key)) {
        whereClause += ` AND ${key} = $${idx + 2}`;
        params.push(value);
      }
    });
  }

  const query = `SELECT * FROM assets WHERE ${whereClause} LIMIT 10000`;
  try {
    const result = await pool.query(query, params);
    // Format conversion would happen here
    res.json({ exported: result.rows.length, format: format || 'json' });
  } catch (err) {
    res.status(500).json({ error: 'Export failed' });
  }
});

// Health check that also validates DB connectivity
app.get('/healthz', async (req, res) => {
  try {
    await pool.query('SELECT 1');
    res.json({ status: 'healthy', timestamp: new Date().toISOString() });
  } catch {
    res.status(503).json({ status: 'unhealthy' });
  }
});

app.listen(process.env.PORT || 3000, () => {
  console.log(`Asset service running on port ${process.env.PORT || 3000}`);
});
